def sent(words, col='#FFF6D8', size=None, w=172, h=90):
    lines = wrap(words.split(), 14)
    sz = size or min(26, min(fit(l, w - 20, 26) for l in lines))
    return S(100, 50 + h + 18, 80) + card(lines, 100 - w / 2, 100 - h / 2, w, h, col=col, size=sz)

def bars(vals, cols, labels):
    o = S(100, 176, 80) + P('M24 170 H184 M24 20 V170', None, 5)
    m = max(vals)
    bw = 120 / len(vals)
    for i, v in enumerate(vals):
        hh = 130 * v / m
        o += R(round(40 + i * (bw + 10)), round(170 - hh), round(bw), round(hh), cols[i % len(cols)], sw=4)
        o += text(labels[i], round(40 + i * (bw + 10) + bw / 2), 190, 12, sw=3)
    return o

def glassof(level, x=100, w=1):
    top, bot = 40, 176
    ly = round(bot - (bot - top - 8) * level)
    o = P(f'M{x - 40} {top} L{x + 40} {top} L{x + 32} {bot} L{x - 32} {bot} Z', '#EAF6FF')
    if level:
        o += P(f'M{x - 40 + 8 * (ly - top) / 136:.0f} {ly} L{x + 40 - 8 * (ly - top) / 136:.0f} {ly} L{x + 32} {bot} L{x - 32} {bot} Z', '#F2A65A', 0)
    return o + P(f'M{x - 40} {top} L{x + 40} {top} L{x + 32} {bot} L{x - 32} {bot} Z')

